import java.io.BufferedReader;import java.io.InputStreamReader;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String input = br.readLine();if (input == null || input.isEmpty()) {return;}int[] freq = new int[256];for (int i = 0; i < input.length(); i++) {char c = input.charAt(i);if (c < 256) {freq[c]++;}}int maxCount = -1;char resultChar = ' ';for (int i = 0; i < 256; i++) {if (freq[i] > maxCount) {maxCount = freq[i];resultChar = (char) i;}}System.out.println(resultChar + " " + maxCount);}}